import { runScript } from '/app/sdk/runner';

async function clickThrough(sdk: any, bot: any, choices: (string | RegExp)[] = [], max = 20) {
  for (let i = 0; i < max; i++) {
    const d = sdk.getDialog();
    if (!d?.isOpen) return true;
    const opts = d.options || [];
    const match = opts.find((o: any) => choices.some(c => typeof c === 'string' ? o.text.toLowerCase().includes(c.toLowerCase()) : c.test(o.text)));
    const cont = opts.find((o: any) => /continue/i.test(o.text));
    const pick = match || cont || opts[0];
    if (!pick) return false;
    console.log('dialog click', pick.index, pick.text);
    await sdk.sendClickDialog(pick.index);
    await sdk.waitForTicks(2);
  }
  return !sdk.getDialog()?.isOpen;
}

